import gurobipy as gp
from gurobipy import GRB
pizza_types = []
revenue = {}
demand = {}
initial_inventory = {}
for rec in LEGACY_RECORDS:
    vals = rec['values']
    i = vals['Product Name']
    pizza_types.append(i)
    revenue[i] = float(vals['Revenue'])
    demand[i] = int(vals['Demand'])
    initial_inventory[i] = int(vals['Initial Inventory'])
if not set(revenue) == set(pizza_types) == set(demand) == set(initial_inventory):
    raise ValueError('Mismatch in pizza_types and parameter keys.')
m = gp.Model('Pizza_Fulfillment')
x_vars = m.addVars(pizza_types, vtype=GRB.INTEGER, lb=0, name='')
for i in pizza_types:
    m.addConstr(x_vars[i] <= min(demand[i], initial_inventory[i]), name=f'cap_{i}')
m.setObjective(gp.quicksum((revenue[i] * x_vars[i] for i in pizza_types)), GRB.MAXIMIZE)
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in x_vars.values():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')